/**
 * Shared modules for trusted plugins (plugin-system.md §8.3).
 *
 * `index.html`'s import map points the shared specifiers at
 * `/qf-shared/*.js` shims (generated by scripts/gen-shared-shims.mjs) that read
 * `globalThis.__QUADFLOW_SHARED__`. Installing the host's own module
 * namespaces here — before any plugin code is imported — makes a trusted
 * plugin's `import { useState } from 'react'` the host's React: hooks, context,
 * portals and @quadflow/* singletons work across the boundary.
 *
 * Keep the keys identical to `SHARED` in scripts/gen-shared-shims.mjs.
 */
import * as React from 'react'
import * as jsxRuntime from 'react/jsx-runtime'
import * as ReactDOM from 'react-dom'
import * as ReactDOMClient from 'react-dom/client'
import * as zustand from 'zustand'
import * as pluginApi from '@quadflow/plugin-api'
import * as ui from '@quadflow/ui'

export const SHARED_SPECIFIERS = [
  'react',
  'react/jsx-runtime',
  'react-dom',
  'react-dom/client',
  'zustand',
  '@quadflow/plugin-api',
  '@quadflow/ui',
] as const

export type SharedSpecifier = (typeof SHARED_SPECIFIERS)[number]

declare global {
  // eslint-disable-next-line no-var
  var __QUADFLOW_SHARED__: Readonly<Record<SharedSpecifier, unknown>> | undefined
}

export function installSharedModules(): void {
  if (globalThis.__QUADFLOW_SHARED__) return
  const shared: Record<SharedSpecifier, unknown> = {
    react: React,
    'react/jsx-runtime': jsxRuntime,
    'react-dom': ReactDOM,
    'react-dom/client': ReactDOMClient,
    zustand,
    '@quadflow/plugin-api': pluginApi,
    '@quadflow/ui': ui,
  }
  Object.defineProperty(globalThis, '__QUADFLOW_SHARED__', {
    value: Object.freeze(shared),
    writable: false,
    configurable: false,
    enumerable: false,
  })
}
